import string

class EncryptionUtils:
    UPPER_OFFSET = 65
    LOWER_OFFSET = 97
    ALPHABET_SIZE = 26

    def __init__(self, key):
        self._key = key

    @property
    def key(self):
        return self._key

    @key.setter
    def key(self, value):
        self._key = value

    def caesar_cipher(self, plaintext, shift):
        return ''.join(self._process_char_cesar(char, shift) for char in plaintext)

    def _process_char_cesar(self, char, shift):
        if not char.isalpha():
            return char
        ascii_offset = self.UPPER_OFFSET if char.isupper() else self.LOWER_OFFSET
        shifted_char = chr((ord(char) - ascii_offset + shift) % self.ALPHABET_SIZE + ascii_offset)
        return shifted_char

    def vigenere_cipher(self, plain_text):
        encrypted_chars = []
        key_index = 0
        for char in plain_text:
            if char.isalpha():
                shift = self._get_shift(key_index)
                shifted_char = chr((ord(char.lower()) - self.LOWER_OFFSET + shift) % self.ALPHABET_SIZE + self.LOWER_OFFSET)
                encrypted_chars.append(shifted_char.upper() if char.isupper() else shifted_char)
                key_index += 1
            else:
                encrypted_chars.append(char)
        return ''.join(encrypted_chars)

    def _get_shift(self, key_index):
        key_char = self._key[key_index % len(self._key)].lower()
        return ord(key_char) - self.LOWER_OFFSET

    def rail_fence_cipher(self, plain_text, rails):
        fence = self._build_fence(plain_text, rails)
        return self._read_fence(fence, plain_text, rails)

    def _build_fence(self, plain_text, rails):
        fence = [['\n' for _ in range(len(plain_text))] for _ in range(rails)]
        direction = -1
        row, col = 0, 0

        for char in plain_text:
            if row == 0 or row == rails - 1:
                direction = -direction
            fence[row][col] = char
            col += 1
            row += direction

        return fence

    def _read_fence(self, fence, plain_text, rails):
        encrypted_chars = []
        for i in range(rails):
            for j in range(len(plain_text)):
                if fence[i][j] != '\n':
                    encrypted_chars.append(fence[i][j])
        return ''.join(encrypted_chars)
